adminMasterRouter.get("/analytics", async (c3) => {
  try {
    const user = await getServerUser(c3.req.raw);
    if (!isAuthorizedMaster(user)) {
      return c3.json({ error: "Unauthorized" }, 401);
    }
    const configs = await queryRaw('SELECT "stadPrice", "proPrice" FROM "SystemConfig" LIMIT 1');
    const config3 = configs[0] || null;
    const stadPrice = Number(config3?.stadPrice) || 9;
    const proPrice = Number(config3?.proPrice) || 19;
    const weddingsByMonth = await prisma.$queryRaw`
            SELECT to_char("createdAt", 'YYYY-MM') as month, COUNT(*)::int as count 
            FROM "Wedding" 
            GROUP BY month 
            ORDER BY month ASC 
            LIMIT 12
        `;
    const packageDist = await prisma.wedding.groupBy({
      by: ["packageType"],
      _count: true
    });
    const giftTotals = await prisma.$queryRaw`
            SELECT currency, COALESCE(SUM(amount), 0)::float as total, COUNT(*)::int as count
            FROM "Gift"
            GROUP BY currency
        `;
    let usdGifts = 0;
    let khrGifts = 0;
    if (Array.isArray(giftTotals)) {
      for (const g2 of giftTotals) {
        if (g2.currency === "USD") usdGifts = g2.total || 0;
        if (g2.currency === "KHR") khrGifts = g2.total || 0;
      }
    }
    let totalPlanRevenue = 0;
    let proCount = 0;
    let premiumCount = 0;
    let freeCount = 0;
    for (const p2 of packageDist) {
      if (p2.packageType === "PRO") {
        proCount = p2._count;
        totalPlanRevenue += p2._count * stadPrice;
      } else if (p2.packageType === "PREMIUM") {
        premiumCount = p2._count;
        totalPlanRevenue += p2._count * proPrice;
      } else {
        freeCount = p2._count;
      }
    }
    return c3.json({
      weddingsByMonth: weddingsByMonth || [],
      packageDist: packageDist || [],
      pricing: { standard: stadPrice, pro: proPrice },
      summary: {
        totalPlanRevenue,
        usdGifts,
        khrGifts,
        proCount,
        premiumCount,
        freeCount,
        totalWeddings: proCount + premiumCount + freeCount
      }
    });
  } catch (error50) {
    console.error("Master Analytics Error:", error50);
    return c3.json({ error: "Internal Server Error" }, 500);
  }
});
